package com.knowflow.interview.speech;
import com.knowflow.exception.BusinessException;
import com.knowflow.interview.service.MockInterviewService;
import com.knowflow.interview.vo.InterviewVos.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.mock.web.MockMultipartFile;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class InterviewSpeechServiceTest {
 JdbcTemplate jdbc;InterviewSpeechService service;InterviewAsrProvider provider;MockInterviewService sessions;
 @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:speech_"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");jdbc=new JdbcTemplate(ds);jdbc.execute("CREATE TABLE mock_interview_session(id BIGINT PRIMARY KEY,user_id BIGINT,deleted INT,status VARCHAR(30))");new ResourceDatabasePopulator(new ClassPathResource("db/h2/migration/V20261016__interview_speech.sql")).execute(ds);jdbc.update("INSERT INTO mock_interview_session VALUES(1,7,0,'IN_PROGRESS')");sessions=mock(MockInterviewService.class);provider=mock(InterviewAsrProvider.class);var session=new SessionVO();session.setStatus("IN_PROGRESS");var q=new QuestionVO();q.setId("q1");session.setQuestions(List.of(q));when(sessions.getOwn(7L,1L)).thenReturn(session);when(provider.capability()).thenReturn(true);when(provider.auditName()).thenReturn("test-provider");when(provider.transcribe(any())).thenReturn("真实转写");service=new InterviewSpeechService(jdbc,sessions,provider,new SpeechProperties(),new DataSourceTransactionManager(ds),new SpeechV2Admission(jdbc));}
 MockMultipartFile audio(){return new MockMultipartFile("file","speech.wav","audio/wav",new AudioValidationTest().wav(16000));}
 @Test void reservationBindingDoesNotMoveWhenSessionAdvances(){jdbc.execute("CREATE TABLE mock_interview_v2_state(session_id BIGINT PRIMARY KEY,user_id BIGINT,state VARCHAR(30),current_question_id VARCHAR(100),followup_depth INT,version BIGINT,current_prompt VARCHAR(1000))");jdbc.update("INSERT INTO mock_interview_v2_state VALUES(1,7,'ASKING','q1',0,2,'原始题干')");var result=service.transcribe(7L,1L,"q1","request01",1000,audio());jdbc.update("UPDATE mock_interview_v2_state SET followup_depth=1,version=4,current_prompt='追问题干',state='FOLLOW_UP'");assertEquals(result,service.transcribe(7L,1L,"q1","request01",1000,audio()));var stored=jdbc.queryForMap("SELECT v2_version,v2_depth,v2_prompt_hash FROM mock_interview_speech WHERE id=?",result.id());assertEquals(2L,((Number)stored.get("v2_version")).longValue());assertEquals(0,((Number)stored.get("v2_depth")).intValue());assertEquals(SpeechV2Admission.promptHash("原始题干"),stored.get("v2_prompt_hash"));assertNotEquals(SpeechV2Admission.promptHash("追问题干"),stored.get("v2_prompt_hash"));verify(provider,times(1)).transcribe(any());}
 @Test void retryReturnsSameRecordWithoutAnotherProviderCharge(){var first=service.transcribe(7L,1L,"q1","request01",1000,audio());var retry=service.transcribe(7L,1L,"q1","request01",1000,audio());assertEquals(first,retry);assertEquals("TRANSCRIBED",first.status());assertEquals("真实转写",first.rawText());verify(provider,times(1)).transcribe(any());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM mock_interview_speech",Integer.class));}
 @Test void changedPayloadConflicts(){service.transcribe(7L,1L,"q1","request01",1000,audio());var e=assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q1","request01",999,audio()));assertEquals(409,e.getCode());verify(provider,times(1)).transcribe(any());}
 @Test void providerFailureIsSanitizedAndNeverRetried(){when(provider.transcribe(any())).thenThrow(new IllegalStateException("Bearer secret"));var result=service.transcribe(7L,1L,"q1","request01",1000,audio());assertEquals("FAILED",result.status());assertFalse(result.error().contains("secret"));service.transcribe(7L,1L,"q1","request01",1000,audio());verify(provider,times(1)).transcribe(any());}
 @Test void finishedSessionAndForeignQuestionNeverCallProvider(){var session=sessions.getOwn(7L,1L);session.setStatus("FINISHED");assertEquals(409,assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q1","request01",1000,audio())).getCode());session.setStatus("IN_PROGRESS");assertEquals(400,assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q2","request01",1000,audio())).getCode());verify(provider,never()).transcribe(any());}
 @Test void disabledConfigurationOffersTextFallback(){when(provider.capability()).thenReturn(false);assertEquals(false,service.capability().get("enabled"));assertEquals(503,assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q1","request01",1000,audio())).getCode());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mock_interview_speech",Integer.class));}
 @Test void v2PausedOrDifferentCurrentQuestionNeverChargesProvider(){jdbc.execute("CREATE TABLE mock_interview_v2_state(session_id BIGINT PRIMARY KEY,user_id BIGINT,state VARCHAR(30),current_question_id VARCHAR(100),followup_depth INT,version BIGINT,current_prompt VARCHAR(1000))");jdbc.update("INSERT INTO mock_interview_v2_state VALUES(1,7,'PAUSED','q1',0,0,'题目一')");assertEquals(409,assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q1","request01",1000,audio())).getCode());jdbc.update("UPDATE mock_interview_v2_state SET state='ANSWERING',current_question_id='q2'");assertEquals(409,assertThrows(BusinessException.class,()->service.transcribe(7L,1L,"q1","request01",1000,audio())).getCode());verify(provider,never()).transcribe(any());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mock_interview_speech",Integer.class));}
 @Test void concurrentSameRequestChargesOnce() throws Exception {var executor=java.util.concurrent.Executors.newFixedThreadPool(2);try{var tasks=List.of((java.util.concurrent.Callable<InterviewSpeechService.SpeechTranscript>)()->service.transcribe(7L,1L,"q1","request01",1000,audio()),()->service.transcribe(7L,1L,"q1","request01",1000,audio()));for(var future:executor.invokeAll(tasks))assertNotNull(future.get());}finally{executor.shutdownNow();}verify(provider,times(1)).transcribe(any());}
}
